 *         this.left = (left===undefined ? null : left)
 *         this.right = (right===undefined ? null : right)
 *     }
 * }
 */

function amountOfTime(root: TreeNode | null, start: number): number {
    const g: Map<number, number[]> = new Map();
    const stk: [TreeNode | null, TreeNode | null][] = [[root, null]];
    while (stk.length) {
        const [node, fa] = stk.pop()!;
        if (!node) {
            continue;
        }
        if (fa) {
            if (!g.has(node.val)) {
                g.set(node.val, []);
            }
            g.get(node.val)!.push(fa.val);
            if (!g.has(fa.val)) {
                g.set(fa.val, []);
            }
            g.get(fa.val)!.push(node.val);
        }
        stk.push([node.right, node]);
        stk.push([node.left, node]);
    }
    const dist = new Map<number, number>();
    const walk: [number, number, number][] = [[start, -1, 0]];
    while (walk.length) {
        const [node, fa, state] = walk.pop()!;
        const nxts = g.get(node) || [];
        if (state === 0) {
            walk.push([node, fa, 1]);
            for (let i = nxts.length - 1; i >= 0; --i) {
                const nxt = nxts[i];
                if (nxt !== fa) {
                    walk.push([nxt, node, 0]);
                }
            }
            continue;
        }
        let best = 0;
        for (const nxt of nxts) {
            if (nxt !== fa) {
                best = Math.max(best, 1 + dist.get(nxt)!);
            }
        }
        dist.set(node, best);
    }
    return dist.get(start)!;
}

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
private:
    int solve(map<TreeNode *, TreeNode *> m, TreeNode *res){

        map<TreeNode *, bool> burnt;
        queue<TreeNode *> q;

        q.push(res);
        burnt[res] = true;
        int ans = 0;

        while(!q.empty()){

            bool flag = false;
            int n = q.size();

            for(int i = 0; i < n; i++){

                TreeNode *front = q.front();
                q.pop();

                if(front -> left and !burnt[front -> left]){
                    q.push(front -> left);
                    burnt[front -> left] = true;
                    flag = true;
                }

                if(front -> right and !burnt[front -> right]){
                    q.push(front -> right);
                    burnt[front -> right] = true;
                    flag = true;
                }

                if(m[front] and !burnt[m[front]]){
                    burnt[m[front]] = true;
                    q.push(m[front]);
                    flag = true;
                }
            }

            if(flag == true)
                ans ++;

        }

        return ans;
    }

public:
    int amountOfTime(TreeNode* root, int start) {

        queue<TreeNode *> q;
        TreeNode *res = NULL;
        map<TreeNode *, TreeNode *> m;

        m[root] = NULL;
        q.push(root);

        while(!q.empty()){

            TreeNode *front = q.front();
            q.pop();

            if(front -> val == start)
                res = front;

            if(front -> left){
                m[front -> left] = front;
                q.push(front -> left);
            }

            if(front -> right){
                m[front -> right] = front;
                q.push(front -> right);
            }
        }

        return solve(m, res);
    }
};

